const countryMap = {
  'deutschland': 'de',
  'germany': 'de',
  'schweiz': 'ch',
  'switzerland': 'ch',
  'suisse': 'ch',
  'österreich': 'at',
  'oesterreich': 'at',
  'austria': 'at'
};

const supportedPhoneCountries = ['de', 'ch', 'at'];

function cleanString(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function normalizeCountry(value) {
  const raw = cleanString(value);
  if (!raw) return '';

  const key = raw.toLowerCase();

  return countryMap[key] || raw;
}

function obviousFakePhone(digits) {
  if (!digits) return true;

  if (digits.length < 7 || digits.length > 15) return true;
  if (/^(\d)\1+$/.test(digits)) return true;
  if (/^(012345|123456|999999|000000)/.test(digits)) return true;

  const uniqueDigits = new Set(digits.split(''));
  if (digits.length >= 8 && uniqueDigits.size <= 2) return true;

  return false;
}

function normalizePhone(rawPhone, countryCode) {
  let phone = cleanString(rawPhone);

  if (!phone) {
    return {
      phone: '',
      sonderfall: false
    };
  }

  phone = phone.replace(/[^\d+]/g, '');

  if (!phone) {
    return {
      phone: '',
      sonderfall: false
    };
  }

  if (phone.startsWith('00')) {
    phone = '+' + phone.slice(2);
  }

  const isSupportedCountry = supportedPhoneCountries.includes(countryCode);

  if (countryCode === 'de') {
    if (phone.startsWith('+49')) {
      phone = phone.slice(1);
    } else if (phone.startsWith('49')) {
      // bleibt so
    } else if (phone.startsWith('0')) {
      phone = '49' + phone.slice(1);
    } else {
      return {
        phone: phone.replace(/\D/g, ''),
        sonderfall: true
      };
    }
  }

  if (countryCode === 'ch') {
    if (phone.startsWith('+41')) {
      phone = phone.slice(1);
    } else if (phone.startsWith('41')) {
      // bleibt so
    } else if (phone.startsWith('0')) {
      phone = '41' + phone.slice(1);
    } else {
      return {
        phone: phone.replace(/\D/g, ''),
        sonderfall: true
      };
    }
  }

  if (countryCode === 'at') {
    if (phone.startsWith('+43')) {
      phone = phone.slice(1);
    } else if (phone.startsWith('43')) {
      // bleibt so
    } else if (phone.startsWith('0')) {
      phone = '43' + phone.slice(1);
    } else {
      return {
        phone: phone.replace(/\D/g, ''),
        sonderfall: true
      };
    }
  }

  if (!isSupportedCountry) {
    let cleaned = phone.replace(/\+/g, '').replace(/\D/g, '');

    if (obviousFakePhone(cleaned)) {
      return {
        phone: '',
        sonderfall: false
      };
    }

    return {
      phone: cleaned,
      sonderfall: true
    };
  }

  phone = phone.replace(/\+/g, '').replace(/\D/g, '');

  if (obviousFakePhone(phone)) {
    return {
      phone: '',
      sonderfall: false
    };
  }

  return {
    phone,
    sonderfall: false
  };
}

return items.map(item => {
  const source = item.json;

  const country = normalizeCountry(source.Land);
  const phoneResult = normalizePhone(source.Telefonnummer, country);

  item.json = {
    Email: cleanString(source.EmailAdresse).toLowerCase(),
    'First Name': cleanString(source.Vorname),
    'Last Name': cleanString(source.Nachname),
    Country: country,
    Zip: cleanString(source.Postleitzahl),
    Phone: phoneResult.phone,
    sonderfall: phoneResult.sonderfall
  };

  return item;
});

return items.map((item, index) => {
  const value = item.json.text ?? item.json;

  if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
    return { json: value };
  }

  if (typeof value !== 'string') {
    throw new Error(`Item ${index}: Weder String noch Objekt gefunden.`);
  }

  try {
    return {
      json: JSON.parse(value.trim()),
    };
  } catch (error) {
    throw new Error(`Item ${index}: Ungültiges JSON: ${value}`);
  }
});

return items.map(item => {
  delete item.json.sonderfall;
  return item;
});

function cleanString(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function obviousFakePhone(digits) {
  if (!digits) return true;
  if (digits.length < 7 || digits.length > 15) return true;
  if (/^(\d)\1+$/.test(digits)) return true;
  if (/^(012345|123456|999999|000000|123456789)/.test(digits)) return true;

  const uniqueDigits = new Set(digits.split(''));
  if (digits.length >= 8 && uniqueDigits.size <= 2) return true;

  return false;
}

function normalizePhone(rawPhone, country) {
  const original = cleanString(rawPhone);
  const countryCode = cleanString(country).toLowerCase();

  if (!original) return '';

  let phone = original.replace(/[^\d+]/g, '');

  if (!phone) return '';

  if (phone.startsWith('00')) {
    phone = '+' + phone.slice(2);
  }

  phone = phone.replace(/\+/g, '').replace(/\D/g, '');

  if (obviousFakePhone(phone)) return '';

  if (countryCode === 'de') {
    if (phone.startsWith('49')) return phone;
    if (phone.startsWith('0')) return '49' + phone.slice(1);

    // Deutsche Mobilnummer ohne führende 0, z. B. 17650335244
    if (/^1[5-7]\d{8,10}$/.test(phone)) {
      return '49' + phone;
    }

    // Keine sicher erkennbare deutsche Telefonnummer
    return '';
  }

  if (countryCode === 'at') {
    if (phone.startsWith('43')) return phone;
    if (phone.startsWith('0')) return '43' + phone.slice(1);

    // Österreichische Mobilnummer ohne führende 0, z. B. 6605239952
    if (/^6\d{7,11}$/.test(phone)) {
      return '43' + phone;
    }

    // Keine sicher erkennbare österreichische Telefonnummer
    return '';
  }

  if (countryCode === 'ch') {
    if (phone.startsWith('41')) return phone;
    if (phone.startsWith('0')) return '41' + phone.slice(1);

    // Schweizer Mobilnummer ohne führende 0, z. B. 791234567
    if (/^7\d{8}$/.test(phone)) {
      return '41' + phone;
    }

    // Keine sicher erkennbare Schweizer Telefonnummer
    return '';
  }

  return original;
}

return items.map(item => {
  item.json.Phone = normalizePhone(item.json.Phone, item.json.Country);
  return item;
});

